import React, { useState, useEffect } from "react";

function App() {
  const [darkMode, setDarkMode] = useState(false);
  const [ingredients, setIngredients] = useState("");
  const [mealType, setMealType] = useState("Breakfast");
  const [cuisine, setCuisine] = useState("");
  const [cookingTime, setCookingTime] = useState("Less than 30 minutes");
  const [complexity, setComplexity] = useState("Beginner");
  const [recipes, setRecipes] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    const html = document.documentElement;
    html.classList.toggle("dark", darkMode);
  }, [darkMode]);

  const handleSubmit = async () => {
    try {
      const response = await fetch("http://localhost:5000/api/generate", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          ingredients,
          mealType,
          cuisine,
          cookingTime,
          complexity,
        }),
      });

      const data = await response.json();
      console.log("API Response:", data);

      if (data.recipe) {
        const recipeData = Array.isArray(data.recipe)
          ? data.recipe
          : [data.recipe];
        setRecipes(recipeData);
      } else {
        setRecipes([]);
      }
    } catch (err) {
      console.error("Error generating recipe:", err);
      setError("Failed to generate recipe.");
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-white to-gray-100 dark:from-gray-900 dark:to-gray-800 flex items-center justify-center p-4 transition-colors duration-300">
      <div className="absolute top-4 right-4">
        <button
          onClick={() => setDarkMode(!darkMode)}
          className="bg-gray-800 dark:bg-white text-white dark:text-black px-4 py-2 rounded shadow hover:opacity-80"
        >
          {darkMode ? "☀️" : "🌙"}
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 w-full max-w-6xl">
        {/* LEFT - Form */}
        <div className="bg-white dark:bg-gray-700 dark:text-white rounded-xl shadow-md p-6">
          <h2 className="text-xl font-bold text-center mb-6">
            Recipe Generator
          </h2>

          <div className="mb-4">
            <label className="block font-semibold mb-1" htmlFor="ingredients">
              Ingredients
            </label>
            <input
              id="ingredients"
              type="text"
              className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
              placeholder="e.g. tomato, potato, onion"
              value={ingredients}
              onChange={(e) => setIngredients(e.target.value)}
            />
          </div>

          <div className="mb-4">
            <label className="block font-semibold mb-1">Meal Type</label>
            <select
              className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
              value={mealType}
              onChange={(e) => setMealType(e.target.value)}
            >
              <option>Breakfast</option>
              <option>Lunch</option>
              <option>Dinner</option>
              <option>Snack</option>
            </select>
          </div>

          <div className="mb-4">
            <label className="block font-semibold mb-1">
              Cuisine Preference
            </label>
            <input
              type="text"
              className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
              placeholder="e.g. Italian, Mexican"
              value={cuisine}
              onChange={(e) => setCuisine(e.target.value)}
            />
          </div>

          <div className="mb-4">
            <label className="block font-semibold mb-1">Cooking Time</label>
            <select
              className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
              value={cookingTime}
              onChange={(e) => setCookingTime(e.target.value)}
            >
              <option>Less than 30 minutes</option>
              <option>30-60 minutes</option>
              <option>More than 1 hour</option>
            </select>
          </div>

          <div className="mb-6">
            <label className="block font-semibold mb-1">Complexity</label>
            <select
              className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white"
              value={complexity}
              onChange={(e) => setComplexity(e.target.value)}
            >
              <option>Beginner</option>
              <option>Intermediate</option>
              <option>Advanced</option>
            </select>
          </div>

          <button
            onClick={handleSubmit}
            className="bg-blue-500 hover:bg-blue-600 text-white font-bold py-2 px-4 rounded w-full"
          >
            Generate Recipe
          </button>
        </div>

        {/* RIGHT - Recipe Output */}
        <div className="bg-white dark:bg-gray-700 rounded-xl shadow-md p-6 overflow-auto max-h-[80vh]">
          <h2 className="text-xl font-bold text-center mb-4">Recipes</h2>
          {error && (
            <p className="text-red-500 dark:text-red-400 text-center mb-4">
              {error}
            </p>
          )}
          {recipes.length === 0 ? (
            <p className="text-gray-500 dark:text-gray-300 text-center">
              No recipes yet. Try generating one!
            </p>
          ) : (
            <div className="grid grid-cols-1 gap-4">
              {recipes.map((recipe, index) => (
                <div
                  key={index}
                  className="border dark:border-gray-600 rounded p-4 bg-gray-50 dark:bg-gray-800 text-sm"
                >
                  <h3 className="text-lg font-bold text-center mb-2">
                    {recipe.title}
                  </h3>
                  <div className="flex flex-wrap justify-center gap-4 text-gray-600 dark:text-gray-300 mb-4">
                    <span>
                      <strong>Prep:</strong> {recipe.prepTime}
                    </span>
                    <span>
                      <strong>Cook:</strong> {recipe.cookTime}
                    </span>
                    <span>
                      <strong>Total:</strong> {recipe.totalTime}
                    </span>
                    <span>
                      <strong>Serves:</strong> {recipe.serves}
                    </span>
                  </div>

                  <div className="mb-3">
                    <h4 className="text-center font-bold italic mb-2">
                      Ingredients
                    </h4>
                    <ul className="list-disc list-inside space-y-1">
                      {recipe.ingredients.map((item, i) => (
                        <li key={i}>{item}</li>
                      ))}
                    </ul>
                  </div>

                  <div className="mb-3">
                    <h4 className="text-center font-bold italic mb-2">
                      Equipment
                    </h4>
                    <ul className="list-disc list-inside space-y-1">
                      {recipe.equipment.map((item, i) => (
                        <li key={i}>{item}</li>
                      ))}
                    </ul>
                  </div>

                  <div className="mb-3">
                    <h4 className="text-center font-bold italic mb-2">
                      Step-by-Step Instructions
                    </h4>
                    <ol className="list-decimal list-inside space-y-1">
                      {recipe.instructions.map((step, i) => (
                        <li key={i}>{step}</li>
                      ))}
                    </ol>
                  </div>

                  <div>
                    <h4 className="text-center font-bold italic mb-2">
                      Optional Tips for Serving and Variations
                    </h4>
                    <ul className="list-disc list-inside space-y-1">
                      {recipe.tips.map((tip, i) => (
                        <li key={i}>{tip}</li>
                      ))}
                    </ul>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default App;
